#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

ARTEMIS_OS_RELEASE="${ARTEMIS_OS_RELEASE:-/etc/os-release}"
ARTEMIS_MOSQUITTO_ETC_DIR="${ARTEMIS_MOSQUITTO_ETC_DIR:-/etc/mosquitto}"
ARTEMIS_CONFIG_FILE="$ARTEMIS_MOSQUITTO_ETC_DIR/conf.d/artemis.conf"
ARTEMIS_PASSWORD_FILE="$ARTEMIS_MOSQUITTO_ETC_DIR/artemis.passwd"
ARTEMIS_ACL_FILE="$ARTEMIS_MOSQUITTO_ETC_DIR/artemis.acl"
ARTEMIS_MQTT_USER="artemis_test"
ARTEMIS_MQTT_TOPIC="artemis/test/climate"
ARTEMIS_MQTT_PAYLOAD='{"temperature_c": 21.5, "humidity_pct": 45.0}'
ENV_FILE=/dev/null

fail_wizard() {
  warn "$1"
  exit 1
}

require_command() {
  command -v "$1" >/dev/null 2>&1 || fail_wizard "Required command not found: $1"
}

service_diagnostics() {
  sudo systemctl --no-pager --full status mosquitto.service || true
  sudo journalctl -u mosquitto.service -n 50 --no-pager || true
}

authenticated_publish() {
  local host="$1" topic="$2" message="$3"
  mosquitto_pub -V mqttv5 -h "$host" -u "$ARTEMIS_MQTT_USER" \
    -P "$ARTEMIS_MQTT_TEST_PASSWORD" -t "$topic" -m "$message" -q 1 -r
}

authenticated_subscribe() {
  local host="$1"
  mosquitto_sub -V mqttv5 -h "$host" -u "$ARTEMIS_MQTT_USER" \
    -P "$ARTEMIS_MQTT_TEST_PASSWORD" -t "$ARTEMIS_MQTT_TOPIC" \
    -q 1 -C 1 -W 5 -v
}

assert_test_payload() {
  local host="$1" actual
  if ! actual=$(authenticated_subscribe "$host"); then
    fail_wizard "Authenticated subscribe failed through $host. Check the password and broker logs."
  fi
  [[ "$actual" == "$ARTEMIS_MQTT_TOPIC $ARTEMIS_MQTT_PAYLOAD" ]] || \
    fail_wizard "Unexpected MQTT payload through $host: $actual"
}

run_wizard() {

TOTAL_STAGES=5

banner "Artemis Mosquitto setup"

stage "Preflight"
say "This installs a password-protected MQTT broker for Artemis on this host."
[[ -r "$ARTEMIS_OS_RELEASE" ]] || fail_wizard "Cannot read $ARTEMIS_OS_RELEASE"
# shellcheck disable=SC1090
source "$ARTEMIS_OS_RELEASE"
[[ "${ID:-}" == "debian" && "${VERSION_ID:-}" == "13" ]] || \
  fail_wizard "Expected Debian 13, found ${PRETTY_NAME:-an unknown operating system}."
[[ "$(uname -m)" == "aarch64" ]] || fail_wizard "Expected ARM64 (aarch64) hardware."
for command_name in apt-get systemctl sudo hostname; do
  require_command "$command_name"
done
sudo -n true >/dev/null 2>&1 || fail_wizard "Passwordless sudo is required for this setup."
say "Detected ${PRETTY_NAME:-Debian 13} on $(uname -m)."
confirm "Install and configure Mosquitto on this Pi?" || fail_wizard "Setup cancelled."

stage "Install packages"
say "Installing Mosquitto and its command-line clients from Debian."
sudo apt-get update
sudo apt-get install -y mosquitto mosquitto-clients
for command_name in mosquitto mosquitto_passwd mosquitto_pub mosquitto_sub journalctl install; do
  require_command "$command_name"
done
mosquitto -h 2>&1 | head -n 1 || true

stage "Configure broker"
say "The password prompt below creates the temporary artemis_test account."
say "The password is not saved by this wizard."
sudo mosquitto_passwd -c "$ARTEMIS_PASSWORD_FILE" "$ARTEMIS_MQTT_USER"

config_temp=$(mktemp)
acl_temp=$(mktemp)
printf '%s\n' \
  'listener 1883' \
  'allow_anonymous false' \
  "password_file $ARTEMIS_PASSWORD_FILE" \
  "acl_file $ARTEMIS_ACL_FILE" > "$config_temp"
printf '%s\n' \
  "user $ARTEMIS_MQTT_USER" \
  'topic readwrite artemis/test/#' > "$acl_temp"

sudo install -o root -g root -m 0644 "$config_temp" "$ARTEMIS_CONFIG_FILE"
sudo install -o root -g mosquitto -m 0640 "$acl_temp" "$ARTEMIS_ACL_FILE"
rm -f "$config_temp" "$acl_temp"
sudo chown root:mosquitto "$ARTEMIS_PASSWORD_FILE"
sudo chmod 0640 "$ARTEMIS_PASSWORD_FILE"
sudo -u mosquitto test -r "$ARTEMIS_PASSWORD_FILE" || fail_wizard "Mosquitto cannot read its password file."
sudo -u mosquitto test -r "$ARTEMIS_ACL_FILE" || fail_wizard "Mosquitto cannot read its ACL file."

stage "Start service"
say "Enabling Mosquitto at boot and loading the Artemis configuration."
sudo systemctl enable --now mosquitto.service
if ! sudo systemctl restart mosquitto.service; then
  service_diagnostics
  fail_wizard "Mosquitto failed to start. Review the status and journal output above."
fi
if ! sudo systemctl is-active --quiet mosquitto.service; then
  service_diagnostics
  fail_wizard "Mosquitto is not active after restart."
fi

stage "Verify MQTT"
say "Re-enter the artemis_test password to run local and LAN checks."
ask_secret ARTEMIS_MQTT_TEST_PASSWORD "MQTT test password:"
[[ -n "$ARTEMIS_MQTT_TEST_PASSWORD" ]] || fail_wizard "The MQTT test password cannot be empty."

if ! authenticated_publish "127.0.0.1" "$ARTEMIS_MQTT_TOPIC" "$ARTEMIS_MQTT_PAYLOAD"; then
  fail_wizard "Authenticated publish failed. Check the password and broker logs."
fi
assert_test_payload "127.0.0.1"

if mosquitto_sub -V mqttv5 -h 127.0.0.1 -t "$ARTEMIS_MQTT_TOPIC" -q 1 -C 1 -W 3 >/dev/null 2>&1; then
  fail_wizard "Anonymous subscription unexpectedly succeeded."
fi
denied_output=$(authenticated_publish "127.0.0.1" "artemis/forbidden" "denied" 2>&1 || true)
[[ "$denied_output" == *'failed: Not authorized.'* ]] || \
  fail_wizard "The broker did not reject a publish outside artemis/test/#."

if ! sudo systemctl restart mosquitto.service; then
  service_diagnostics
  fail_wizard "Mosquitto failed to restart during the retained-message test."
fi
assert_test_payload "127.0.0.1"

lan_ip=''
for address in $(hostname -I); do
  if [[ "$address" == *.* && "$address" != 127.* ]]; then
    lan_ip="$address"
    break
  fi
done
[[ -n "$lan_ip" ]] || fail_wizard "No non-loopback LAN IPv4 address was found."
if ! authenticated_publish "$lan_ip" "$ARTEMIS_MQTT_TOPIC" "$ARTEMIS_MQTT_PAYLOAD"; then
  fail_wizard "Authenticated publish failed through LAN address $lan_ip."
fi
assert_test_payload "$lan_ip"
unset ARTEMIS_MQTT_TEST_PASSWORD

say "Mosquitto is active on port 1883 and the retained MQTT checks passed."
say "Config: $ARTEMIS_CONFIG_FILE"
say "ACL: $ARTEMIS_ACL_FILE"
say "Test topic: $ARTEMIS_MQTT_TOPIC"

finish
}

run_wizard "$@"; exit
